-- GENERATED by tools/gen_state_mod.py from templates/state_names and data/states/us_colorado; edit those, not this file.
-- Name set scripts for "square_names_us_colorado" (docs/wiki/modding/misc/names.md): towns by climate, generic streets.
-- Person names use the base game's usa lists (::/names/names.script@personNameScriptFn, set in the .names.lua).
-- The engine asks for towns once per new game (num = town count) and for streets with num = -1 only
-- (docs/findings.md "Street names and Road Stops"). Plain Lua, pre-5.3; exports via data().

local MOD_ID = "square_names_us_colorado"
local TAG = "[" .. MOD_ID .. "] "

local function req(file)
	return require(MOD_ID .. "::/" .. MOD_ID .. "/" .. file)
end

local function log(msg)
	pcall(print, TAG .. msg)
end

---------------------------------------------------------------------------
-- CLIMATE ROUTE (Probe 3, 2026-10-08, docs/findings.md): the name scripts have no api.engine, but our runFn
-- (content/square_names_us_colorado/mod.script.lua) runs in the same Lua state and leaves the climate in the raw global
-- SQUARE_NAMES_US_COLORADO_RUNFN and in sn_shared.lua. Read without assigning anything. getConfigDict stays as a harmless last
-- try for a future build that gives these scripts api.engine. Nothing found = no climate: the whole state.
local function fromRunFn(g)
	if type(g) == "table" and type(g.climate) == "string" and g.climate ~= "" then return g.climate end
	return nil
end

local function currentClimate()
	local _, raw = pcall(function() return rawget(_G, "SQUARE_NAMES_US_COLORADO_RUNFN") end)
	local c = fromRunFn(raw)
	if c == nil then
		local _, plain = pcall(function() return _G["SQUARE_NAMES_US_COLORADO_RUNFN"] end)
		c = fromRunFn(plain)
	end
	if c == nil then
		local _, shared = pcall(function() return req("sn_shared.lua").runFn end)
		c = fromRunFn(shared)
	end
	if c then return c, "runFn" end
	local ok, d = pcall(function() return api.engine.config.getConfigDict().climate end)
	if ok and type(d) == "string" and d ~= "" then return d, "configDict" end
	return nil, "none"
end
---------------------------------------------------------------------------

local function townRows()
	local ok, t = pcall(req, "data/towns.lua")
	if ok and type(t) == "table" then return t end
	log("could not load towns: " .. tostring(t))
	return {}
end

local function stateData()
	local ok, s = pcall(req, "data/state.lua")
	if ok and type(s) == "table" then return s end
	return {}
end

--- The engine needs exactly `num` names ("Town name generation function did not return the expected number").
local function plainTowns(rows, num)
	local res = {}
	if #rows == 0 then rows = { { n = "Town" } } end
	if num < 0 then num = #rows end
	for i = 1, num do res[i] = rows[((i - 1) % #rows) + 1].n end
	return res
end

local function townsFn(captureParams, params)
	local num = (params and tonumber(params.num)) or -1
	local rows = townRows()
	local ok, res = pcall(function()
		local logic = req("sn_logic.lua")
		local weights, how, climate
		if type(captureParams) == "table" and type(captureParams.tags) == "table" then
			weights, how = logic.regionWeights(captureParams.tags), "region " .. tostring(captureParams.setId)
		else
			climate, how = currentClimate()
			weights = logic.climateWeights(stateData(), climate)
		end
		local out = logic.sampleTowns(rows, num, weights)
		log(string.format("towns num=%s climate=%s via %s -> %s%d names, first %s", tostring(num), tostring(climate),
			how, weights and "" or "whole state, ", #out, tostring(out[1])))
		return out
	end)
	if ok and type(res) == "table" and (num < 0 or #res == num) then return res end
	log("towns failed, plain list: " .. tostring(res))
	return plainTowns(rows, num)
end

local function streetsFn(_captureParams, params)
	local num = (params and tonumber(params.num)) or -1
	local ok, streets = pcall(req, "data/streets.lua")
	if not ok or type(streets) ~= "table" or #streets == 0 then
		log("could not load streets: " .. tostring(streets))
		streets = { "Main Street" }
	end
	local res = {}
	if num < 0 then
		local okL, logic = pcall(req, "sn_logic.lua")
		if okL then return logic.shuffle(streets) end
		for i = 1, #streets do res[i] = streets[i] end
		return res
	end
	for i = 1, num do res[i] = streets[math.random(1, #streets)] end
	return res
end

function data()
	return {
		townsFn = townsFn,
		streetsFn = streetsFn,
	}
end
